// Map GitHub stats → analytics_events rows
// Refs: docs/specs/devrel-analytics-stack.md Decision 4
const repoData = $('GitHub Repository Stats').first().json;
const trafficData = $('GitHub Traffic Views').first().json;
const rows = [];
const occurredAt = new Date().toISOString();
const repo = `${$env.GITHUB_ORG}/${$env.GITHUB_REPO}`;
const contentId = `github:${repo}`;

// Stars
if (repoData.stargazers_count !== undefined) {
  rows.push({
    platform: 'github',
    content_id: contentId,
    event_type: 'star',
    occurred_at: occurredAt,
    metric_value: repoData.stargazers_count,
    metadata: JSON.stringify({ repo, forks: repoData.forks_count })
  });
}

// Traffic views (last 14 days, broken by day)
const views = trafficData.views || [];
for (const dayView of views) {
  rows.push({
    platform: 'github',
    content_id: contentId,
    event_type: 'view',
    occurred_at: dayView.timestamp || occurredAt,
    metric_value: dayView.count || 0,
    metadata: JSON.stringify({ uniques: dayView.uniques, repo })
  });
}

return rows.map(row => ({ json: row }));
